INSERT OR IGNORE INTO course_assignments (id, course_id, class_id, due_date) VALUES ('0fd3a286-c405-5e5d-a5a4-63c8c9c0aefc', '6282b6ca-259e-5661-a9b7-76d8e10b4276', '4aaa1400-fcb5-5271-a59a-3cff7d2e0778', '2026-11-08');
WITH src(j) AS (VALUES ('{"schema_version":"1.0","lesson":{"slug":"diag-data-ai-class-1","subject":"data-ai","title":"Computers, Data & AI Check-In: Where Am I?","summary":"A friendly tour of instructions, sorting, graphs, smart machines and staying safe online, so we can see what you already know.","age_band":"7-8","difficulty":1,"estimated_minutes":60,"unit":"Week 1: Where am I?","learning_objectives":["Show what I know about instructions and patterns","Show what I know about sorting and simple graphs","Show what I know about smart machines and staying safe"],"tags":["week-1","diagnostic"],"curriculum":{"course":"data-ai-class-1","semester":1,"week":1}},"blocks":[{"type":"heading","text":"Welcome, Computer Explorer!"},{"type":"text","markdown":"Computers follow **instructions** exactly, one step at a time.\n\nA list of clear steps is called an **algorithm**.\n\nToday is a **check-in** to see what you know. No computer is needed!"},{"type":"image","emoji":"🤖","alt":"Beep boop! Robots follow instructions one step at a time.","caption":"Beep boop! Robots follow instructions one step at a time."},{"type":"heading","text":"Stop 1: Instructions in order"},{"type":"text","markdown":"If you give a robot the steps for a sandwich in the wrong order, you get a very silly sandwich!\n\nThe **order** of the steps matters."},{"type":"explainer","title":"A sandwich in the right order","scenes":[{"caption":"First, put the bread on the plate.","items":[{"id":"b","emoji":"🍞","x":50,"y":60,"size":3,"anim":"none"}]},{"caption":"Next, add the cheese.","items":[{"id":"b","emoji":"🍞","x":50,"y":60,"size":3,"anim":"none"},{"id":"c","emoji":"🧀","x":50,"y":40,"size":3,"anim":"grow"}]},{"caption":"Last, put the top bread on. Yum!","items":[{"id":"b","emoji":"🍞","x":50,"y":65,"size":3,"anim":"none"},{"id":"c","emoji":"🧀","x":50,"y":50,"size":3,"anim":"none"},{"id":"t","emoji":"🍞","x":50,"y":30,"size":3,"anim":"bounce"}]}]},{"type":"check","question":{"type":"order","prompt":"Put these steps for brushing teeth in order.","hint":"What do you do first?","points":2,"items":[{"id":"i2","text":"Brush your teeth"},{"id":"i3","text":"Rinse your mouth"},{"id":"i1","text":"Put paste on the brush"}],"answer":["i1","i2","i3"]}},{"type":"heading","text":"Stop 2: Patterns and sorting"},{"type":"text","markdown":"Computers love **patterns**. A pattern repeats in the same order.\n\nWe can also **sort** things into groups, such as animals that fly and animals that swim."},{"type":"image","emoji":"🔴🔺🔴🔺🔴🔺","alt":"A pattern: circle, triangle, circle, triangle ...","caption":"A pattern: circle, triangle, circle, triangle ..."},{"type":"explainer","title":"Sorting into groups","scenes":[{"caption":"Here are four things.","items":[{"id":"a","emoji":"🐦","x":20,"y":40,"size":3,"anim":"none"},{"id":"b","emoji":"🐟","x":40,"y":40,"size":3,"anim":"none"},{"id":"c","emoji":"🦅","x":60,"y":40,"size":3,"anim":"none"},{"id":"d","emoji":"🐠","x":80,"y":40,"size":3,"anim":"none"}]},{"caption":"Birds fly. Fish swim. Let us sort them.","items":[{"id":"a","emoji":"🐦","x":25,"y":70,"size":3,"anim":"none","label":"fly"},{"id":"c","emoji":"🦅","x":40,"y":70,"size":3,"anim":"none","label":"fly"},{"id":"b","emoji":"🐟","x":62,"y":70,"size":3,"anim":"none","label":"swim"},{"id":"d","emoji":"🐠","x":78,"y":70,"size":3,"anim":"none","label":"swim"}]}]},{"type":"check","question":{"type":"multiple_choice","prompt":"Which one belongs in the group of fruits?","hint":"You can eat it.","options":[{"id":"a","text":"🚗"},{"id":"b","text":"🐶"},{"id":"c","text":"🍌"}],"answer":["c"]}},{"type":"activity","title":"Be the robot","materials":["A grown-up","A small toy or a cushion"],"instructions":["Ask the grown-up to give you instructions: step forward, turn left, pick up the toy.","Do only what they say, one step at a time.","Now swap! Can you give clear instructions?"]},{"type":"heading","text":"Stop 3: Data and graphs"},{"type":"text","markdown":"**Data** is information we collect. We can count things with tally marks.\n\nWe can draw a **pictogram** where each picture stands for one item."},{"type":"chart","kind":"tally","title":"Tally marks: favourite pets","rows":[{"label":"Cats","value":3},{"label":"Dogs","value":5},{"label":"Fish","value":2}],"caption":"Each stroke is one vote. Five is a bundle."},{"type":"chart","kind":"pictogram","title":"A pictogram: fruit we like","rows":[{"label":"Apples","value":3,"emoji":"🍎"},{"label":"Bananas","value":5,"emoji":"🍌"},{"label":"Mangoes","value":4,"emoji":"🥭"}],"each":1,"caption":"Each picture is one child''s vote. Bananas have the most."},{"type":"check","question":{"type":"multiple_choice","prompt":"A pictogram shows 3 🍎 for apples and 5 🍌 for bananas. Which fruit is more popular?","hint":"Count the pictures.","options":[{"id":"a","text":"Apples"},{"id":"b","text":"They are the same"},{"id":"c","text":"Bananas"}],"answer":["c"]}},{"type":"heading","text":"Stop 4: Inputs, outputs and bugs"},{"type":"text","markdown":"An **input** is how we tell a computer something, like a keyboard or a touch screen.\n\nAn **output** is how it tells us something, like a screen or a speaker.\n\nA **bug** is a mistake in the instructions. **Debugging** means fixing it."},{"type":"image","emoji":"⌨️🖱️🖥️🔊","alt":"A keyboard and mouse are inputs. A screen and speaker are outputs.","caption":"A keyboard and mouse are inputs. A screen and speaker are outputs."},{"type":"check","question":{"type":"multiple_choice","prompt":"A robot must go forward 2 steps and then turn left. It turned left first. What is the problem?","hint":"Look at the order.","options":[{"id":"a","text":"The robot is broken"},{"id":"b","text":"The steps are in the wrong order"},{"id":"c","text":"The robot is too slow"}],"answer":["b"]}},{"type":"heading","text":"Stop 5: Smart machines and staying safe"},{"type":"text","markdown":"Some machines can learn from examples. They are called **AI**, short for **artificial intelligence**.\n\nA phone that understands your voice uses AI. But computers do not think or feel like people.\n\nOnline, keep your **password** secret. Always ask a grown-up before you share anything."},{"type":"image","emoji":"📱🗣️","alt":"A phone that listens to your voice uses AI to understand the words.","caption":"A phone that listens to your voice uses AI to understand the words."},{"type":"check","question":{"type":"true_false","prompt":"It is safe to tell strangers online your password.","hint":"A password is a secret.","answer":[false]}},{"type":"reveal","prompt":"Can you think of a machine at home that follows instructions?","answer_markdown":"A washing machine, a microwave, a TV remote or a toy robot all follow instructions."},{"type":"brain_game","game":"memory_match","title":"Computer pairs","goal":"Turn over two cards and find the pairs.","emojis":["⌨️","🖥️","🖱️","🔊","📱","🤖"]},{"type":"summary","points":["Computers follow instructions in order. A list of steps is an algorithm.","We can sort things and spot patterns.","Data can be shown with tally marks and pictograms.","A bug is a mistake. Debugging fixes it.","AI learns from examples, and we keep our password secret."]},{"type":"callout","style":"tip","markdown":"When you are ready, start the quiz. It has 15 questions and takes about 15 minutes. Do your best!"},{"type":"glossary","terms":[{"term":"instructions","meaning":"Clear steps that tell a computer or a robot what to do."},{"term":"algorithm","meaning":"A list of clear steps to do a job."},{"term":"check-in","meaning":"A friendly game that shows us what you know. It is not a test."},{"term":"order","meaning":"What comes first, next and last."},{"term":"patterns","meaning":"Things that repeat in the same order."},{"term":"sort","meaning":"To put things into groups that go together."},{"term":"data","meaning":"Information we collect, like how many children like apples."},{"term":"pictogram","meaning":"A graph that uses pictures to show how many."},{"term":"input","meaning":"How we tell a computer something, like a keyboard."},{"term":"output","meaning":"How a computer tells us something, like a screen."},{"term":"bug","meaning":"A mistake in a set of instructions."},{"term":"debugging","meaning":"Finding and fixing a bug."},{"term":"AI","meaning":"Short for artificial intelligence. A computer that learns from examples."},{"term":"artificial intelligence","meaning":"A computer program that learns from lots of examples to do a job."},{"term":"password","meaning":"A secret word that keeps your accounts safe. Never share it."}]}],"quiz":{"pass_percent":1,"shuffle_questions":false,"shuffle_options":true,"max_attempts":null,"questions":[{"ref":"q1","type":"order","prompt":"Put these steps for planting a seed in order.","hint":"What do you do first?","explanation":"Dig, put in the seed, cover it, then water.","skill_tag":"algorithms.order","points":2,"items":[{"id":"i2","text":"Put the seed in"},{"id":"i4","text":"Give it water"},{"id":"i3","text":"Cover it with soil"},{"id":"i1","text":"Dig a small hole"}],"answer":["i1","i2","i3","i4"]},{"ref":"q2","type":"multiple_choice","prompt":"What is an algorithm?","hint":"Think of a recipe.","explanation":"An algorithm is a list of clear steps.","skill_tag":"algorithms.meaning","options":[{"id":"a","text":"A funny picture"},{"id":"b","text":"A game"},{"id":"c","text":"A type of computer"},{"id":"d","text":"A list of steps to do a job"}],"answer":["d"]},{"ref":"q3","type":"multiple_choice","prompt":"What comes next? 🔺 🔵 🔺 🔵 🔺 ...","hint":"Say the pattern out loud.","explanation":"The pattern is triangle, circle. After a triangle comes a circle.","skill_tag":"patterns.next","options":[{"id":"a","text":"🔺"},{"id":"b","text":"🔵"},{"id":"c","text":"🟢"}],"answer":["b"]},{"ref":"q4","type":"hotspot","prompt":"Tap the one that does NOT belong with the animals.","hint":"Which one is not alive?","explanation":"Dogs, cats and rabbits are animals. A car is not.","skill_tag":"sorting.groups","scene":{"items":[{"id":"h1","emoji":"🐶","label":"dog","x":20,"y":40,"size":3},{"id":"h2","emoji":"🐱","label":"cat","x":50,"y":40,"size":3},{"id":"h3","emoji":"🐰","label":"rabbit","x":80,"y":40,"size":3},{"id":"h4","emoji":"🚗","label":"car","x":50,"y":80,"size":3}],"show_labels":false},"answer":["h4"]},{"ref":"q5","type":"match","prompt":"Match each animal to what it does.","hint":"Think about how each moves.","explanation":"Birds fly, fish swim and dogs walk.","skill_tag":"sorting.match","points":2,"left":[{"id":"l1","text":"🐦 Bird"},{"id":"l2","text":"🐟 Fish"},{"id":"l3","text":"🐕 Dog"}],"right":[{"id":"r2","text":"Swims"},{"id":"r1","text":"Flies"},{"id":"r3","text":"Walks"}],"answer":{"l1":"r1","l2":"r2","l3":"r3"}},{"ref":"q6","type":"number","prompt":"A tally chart has one bundle of five and 3 more strokes. How many is that?","hint":"Count the bundle as five.","explanation":"5 and 3 more makes 8.","skill_tag":"data.tally","answer":{"value":8,"tolerance":0}},{"ref":"q7","type":"multiple_choice","prompt":"In a pictogram, red cars have 5 pictures and blue cars have 2. How many more red cars are there?","hint":"Take away the blue cars from the red cars.","explanation":"5 take away 2 leaves 3.","skill_tag":"data.read_graph","options":[{"id":"a","text":"2"},{"id":"b","text":"7"},{"id":"c","text":"5"},{"id":"d","text":"3"}],"answer":["d"]},{"ref":"q8","type":"slider","prompt":"In a pictogram each 🍎 stands for 2 apples. There are 4 🍎. How many apples?","hint":"Count in 2s.","explanation":"4 pictures of 2 each is 2, 4, 6, 8.","skill_tag":"data.pictogram","range":{"step":1,"min":0,"max":20},"answer":{"value":8,"tolerance":0}},{"ref":"q9","type":"multiple_choice","prompt":"A robot should put on its coat and then go outside. It goes outside first. What is the problem?","hint":"Look at the order of the steps.","explanation":"The turn came before the forward steps, so the order is wrong.","skill_tag":"debugging.spot","options":[{"id":"a","text":"It has no batteries"},{"id":"b","text":"The steps are in the wrong order"},{"id":"c","text":"It went too fast"}],"answer":["b"]},{"ref":"q10","type":"multiple_choice","prompt":"Which one is an INPUT device (you use it to tell the computer something)?","hint":"You press its keys.","explanation":"A keyboard sends information into the computer.","skill_tag":"computers.input_output","options":[{"id":"a","text":"A speaker"},{"id":"b","text":"A printer"},{"id":"c","text":"A screen"},{"id":"d","text":"A keyboard"}],"answer":["d"]},{"ref":"q11","type":"multiple_choice","prompt":"Which of these uses AI?","hint":"It learns from examples.","explanation":"A voice assistant uses AI to understand words.","skill_tag":"ai.meaning","options":[{"id":"a","text":"A light switch"},{"id":"b","text":"A wooden toy"},{"id":"c","text":"A paper book"},{"id":"d","text":"A phone that understands your voice"}],"answer":["d"]},{"ref":"q12","type":"multiple_choice","prompt":"Which is the safest thing to do with your password?","hint":"A password is like a secret key.","explanation":"A password should be kept secret.","skill_tag":"safety.password","options":[{"id":"a","text":"Write it on a wall"},{"id":"b","text":"Share it online"},{"id":"c","text":"Tell your friends"},{"id":"d","text":"Keep it secret"}],"answer":["d"]},{"ref":"q13","type":"true_false","prompt":"It is safe to tell a stranger online where you live.","hint":"A stranger is someone you do not know.","explanation":"Never tell strangers online personal things.","skill_tag":"safety.online","answer":[false]},{"ref":"q14","type":"fill_blank","prompt":"Fill in the gaps.","hint":"Think of the words from the lesson.","explanation":"A list of steps is an algorithm and a mistake is a bug.","skill_tag":"algorithms.vocab","points":2,"text":"A step-by-step list is called an {b1}. A mistake in it is called a {b2}.","blanks":[{"id":"b1","options":[{"id":"a","text":"picture"},{"id":"b","text":"algorithm"},{"id":"c","text":"pattern"}]},{"id":"b2","options":[{"id":"a","text":"song"},{"id":"b","text":"bug"},{"id":"c","text":"game"}]}],"answer":{"b1":"b","b2":"b"}},{"ref":"q15","type":"multi_select","prompt":"Which of these are safe things to do online? Pick all that apply.","hint":"Think about staying safe.","explanation":"Keep passwords secret and ask a grown-up first.","skill_tag":"safety.online","options":[{"id":"a","text":"Ask a grown-up before sharing"},{"id":"b","text":"Click on every link"},{"id":"c","text":"Share my password with a friend"},{"id":"d","text":"Keep my password secret"}],"answer":["d","a"]}]}}')) INSERT OR IGNORE INTO lessons (id, slug, subject_id, title, summary, age_band, difficulty, estimated_minutes, unit, sort_order, status, current_version, content_json, source_json) SELECT 'e73f724b-6aff-5fd5-a73a-572221e46ca6', json_extract(j,'$.lesson.slug'), json_extract(j,'$.lesson.subject'), json_extract(j,'$.lesson.title'), json_extract(j,'$.lesson.summary'), json_extract(j,'$.lesson.age_band'), json_extract(j,'$.lesson.difficulty'), json_extract(j,'$.lesson.estimated_minutes'), json_extract(j,'$.lesson.unit'), 1, 'published', 1, json_extract(j,'$.blocks'), j FROM src;
