INSERT OR IGNORE INTO course_assignments (id, course_id, class_id, due_date) VALUES ('643f4405-f490-5599-ae0c-6ea58e04c359', '902cf72b-3cc6-5944-a208-0b4b9872a8c8', '4aaa1400-fcb5-5271-a59a-3cff7d2e0778', '2026-11-08');
WITH src(j) AS (VALUES ('{"schema_version":"1.0","lesson":{"slug":"diag-english-class-1","subject":"english","title":"English Check-In: Where Am I?","summary":"A friendly tour of letters and sounds, rhymes, sentences, naming and action words, opposites and a little story.","age_band":"7-8","difficulty":1,"estimated_minutes":60,"unit":"Week 1: Where am I?","learning_objectives":["Show what I know about letters, sounds and rhymes","Show what I know about sentences, nouns and verbs","Show what I can understand from a little story"],"tags":["week-1","diagnostic"],"curriculum":{"course":"english-class-1","semester":1,"week":1}},"blocks":[{"type":"heading","text":"Welcome, Word Explorer!"},{"type":"text","markdown":"Today is a **check-in**. We will play with letters, sounds, words and a little story.\n\nThere are no wrong guesses, only tries!"},{"type":"image","emoji":"📚","alt":"Let us explore words!","caption":"Let us explore words!"},{"type":"heading","text":"Stop 1: Letters and sounds"},{"type":"text","markdown":"The **alphabet** has 26 letters. Each letter makes a **sound**.\n\nPut the sounds together and you can read a word!"},{"type":"image","emoji":"🔤","alt":"The alphabet: a, b, c and 23 more letters.","caption":"The alphabet: a, b, c and 23 more letters."},{"type":"explainer","title":"Sounds make a word","scenes":[{"caption":"Here are three sounds.","items":[{"id":"c","emoji":"🔵","x":25,"y":50,"size":3,"anim":"none","label":"c"},{"id":"a","emoji":"🔴","x":50,"y":50,"size":3,"anim":"none","label":"a"},{"id":"t","emoji":"🟢","x":75,"y":50,"size":3,"anim":"none","label":"t"}]},{"caption":"c ... a ... t. Say them slowly.","items":[{"id":"c","emoji":"🔵","x":25,"y":50,"size":3,"anim":"bounce","label":"c"},{"id":"a","emoji":"🔴","x":50,"y":50,"size":3,"anim":"none","label":"a"},{"id":"t","emoji":"🟢","x":75,"y":50,"size":3,"anim":"none","label":"t"}]},{"caption":"Squash them together: cat!","items":[{"id":"c","emoji":"🔵","x":35,"y":50,"size":2,"anim":"none","label":"c"},{"id":"a","emoji":"🔴","x":50,"y":50,"size":2,"anim":"none","label":"a"},{"id":"t","emoji":"🟢","x":65,"y":50,"size":2,"anim":"none","label":"t"},{"id":"cat","emoji":"🐱","x":50,"y":22,"size":3,"anim":"bounce","label":"cat"}]}]},{"type":"check","question":{"type":"multiple_choice","prompt":"Which word starts with the same sound as snake?","hint":"Say ''ssss'' at the start.","options":[{"id":"a","text":"ball"},{"id":"b","text":"sun"},{"id":"c","text":"cat"}],"answer":["b"]}},{"type":"heading","text":"Stop 2: Rhymes"},{"type":"text","markdown":"Words that **rhyme** sound the same at the end. Cat and hat rhyme.\n\nThey both end in the sound ''at''."},{"type":"image","emoji":"🐱🎩","alt":"Cat and hat rhyme. They both end in ''at''.","caption":"Cat and hat rhyme. They both end in ''at''."},{"type":"check","question":{"type":"match","prompt":"Match the words that rhyme.","hint":"Listen to the ends of the words.","points":2,"left":[{"id":"l1","text":"cat"},{"id":"l2","text":"dog"},{"id":"l3","text":"star"}],"right":[{"id":"r2","text":"log"},{"id":"r1","text":"hat"},{"id":"r3","text":"car"}],"answer":{"l1":"r1","l2":"r2","l3":"r3"}}},{"type":"heading","text":"Stop 3: Sentences"},{"type":"text","markdown":"A **sentence** tells us a whole idea. It starts with a **capital letter** and ends with a **full stop**."},{"type":"explainer","title":"Building a sentence","scenes":[{"caption":"First word, with a capital letter.","items":[{"id":"w1","emoji":"🟦","x":20,"y":50,"size":3,"anim":"pulse","label":"The"}]},{"caption":"Add more words.","items":[{"id":"w1","emoji":"🟦","x":15,"y":50,"size":2,"anim":"none","label":"The"},{"id":"w2","emoji":"🟨","x":38,"y":50,"size":2,"anim":"grow","label":"cat"},{"id":"w3","emoji":"🟩","x":60,"y":50,"size":2,"anim":"grow","label":"sat"}]},{"caption":"End with a full stop.","items":[{"id":"w1","emoji":"🟦","x":12,"y":50,"size":2,"anim":"none","label":"The"},{"id":"w2","emoji":"🟨","x":32,"y":50,"size":2,"anim":"none","label":"cat"},{"id":"w3","emoji":"🟩","x":52,"y":50,"size":2,"anim":"none","label":"sat"},{"id":"w4","emoji":"⚫","x":72,"y":55,"size":2,"anim":"bounce","label":"full stop"}]}]},{"type":"check","question":{"type":"order","prompt":"Put the words in order to make a sentence.","hint":"Start with the word I.","points":2,"items":[{"id":"i3","text":"red"},{"id":"i4","text":"apples."},{"id":"i2","text":"like"},{"id":"i1","text":"I"}],"answer":["i1","i2","i3","i4"]}},{"type":"activity","title":"Word cards","materials":["Paper","Scissors","Pencil"],"instructions":["Write the words: The, dog, can, run, fast.","Cut them up and mix them.","Put them in order to make a sentence. Say it out loud!"]},{"type":"heading","text":"Stop 4: Naming words and action words"},{"type":"text","markdown":"A **noun** is a naming word, like frog, ball or Mum.\n\nA **verb** is an action word, like jump, run or eat."},{"type":"explainer","title":"Noun and verb","scenes":[{"caption":"A frog is a noun. It names a thing.","items":[{"id":"f","emoji":"🐸","x":50,"y":55,"size":3,"anim":"none","label":"noun"}]},{"caption":"Jump is a verb. It is something the frog does.","items":[{"id":"f","emoji":"🐸","x":50,"y":25,"size":3,"anim":"bounce","label":"verb: jump"}]}]},{"type":"check","question":{"type":"multiple_choice","prompt":"Which one is an action word?","hint":"You can do it with your body.","options":[{"id":"a","text":"table"},{"id":"b","text":"red"},{"id":"c","text":"jump"}],"answer":["c"]}},{"type":"heading","text":"Stop 5: Opposites"},{"type":"text","markdown":"**Opposites** are words that mean the very opposite. Hot and cold are opposites."},{"type":"explainer","title":"Opposites","scenes":[{"caption":"This tea is hot.","items":[{"id":"a","emoji":"☕","x":50,"y":55,"size":3,"anim":"float","label":"hot"}]},{"caption":"This ice is cold. Hot and cold are opposites.","items":[{"id":"a","emoji":"🧊","x":50,"y":55,"size":3,"anim":"none","label":"cold"}]}]},{"type":"check","question":{"type":"match","prompt":"Match each word to its opposite.","hint":"Think of the opposite.","points":2,"left":[{"id":"l1","text":"big"},{"id":"l2","text":"up"},{"id":"l3","text":"happy"}],"right":[{"id":"r2","text":"down"},{"id":"r1","text":"small"},{"id":"r3","text":"sad"}],"answer":{"l1":"r1","l2":"r2","l3":"r3"}}},{"type":"heading","text":"Stop 6: A little story"},{"type":"text","markdown":"Read this story. Pip has a red kite. The wind is strong. Pip runs and the kite goes up, up, up!"},{"type":"image","emoji":"🪁","alt":"Pip''s red kite flies up, up, up.","caption":"Pip''s red kite flies up, up, up."},{"type":"check","question":{"type":"multiple_choice","prompt":"What colour is Pip''s kite?","hint":"Read the first sentence.","options":[{"id":"a","text":"Blue"},{"id":"b","text":"Green"},{"id":"c","text":"Red"}],"answer":["c"]}},{"type":"reveal","prompt":"What do you think Pip does next?","answer_markdown":"Any idea that fits the story is great. Maybe Pip waves to a friend!"},{"type":"brain_game","game":"memory_match","title":"Match the pictures","goal":"Turn over two cards and find the pairs.","emojis":["🐱","🎩","🐸","🪁","📚","🔤"]},{"type":"summary","points":["The alphabet has 26 letters and each makes a sound.","Rhyming words sound the same at the end.","A sentence starts with a capital letter and ends with a full stop.","A noun names, a verb is an action, and opposites mean the very opposite."]},{"type":"callout","style":"tip","markdown":"When you are ready, start the quiz. It has 15 questions and takes about 15 minutes. Do your best!"},{"type":"glossary","terms":[{"term":"check-in","meaning":"A friendly game that shows us what you know. It is not a test."},{"term":"alphabet","meaning":"All the letters, from a to z. There are 26."},{"term":"sound","meaning":"What a letter says when we read a word."},{"term":"rhyme","meaning":"Words that sound the same at the end, like cat and hat."},{"term":"sentence","meaning":"A group of words that tells a whole idea."},{"term":"capital letter","meaning":"A big letter, used at the start of a sentence and for names."},{"term":"full stop","meaning":"The dot at the end of a sentence."},{"term":"noun","meaning":"A naming word, like frog, ball or Mum."},{"term":"verb","meaning":"An action word, like jump, run or eat."},{"term":"opposites","meaning":"Words that mean the very opposite, like hot and cold."}]}],"quiz":{"pass_percent":1,"shuffle_questions":false,"shuffle_options":true,"max_attempts":null,"questions":[{"ref":"q1","type":"multiple_choice","prompt":"Which word starts with the same sound as fish?","hint":"Say ''ffff''.","explanation":"Fish and fan both start with ''f''.","skill_tag":"phonics.initial_sound","options":[{"id":"a","text":"sun"},{"id":"b","text":"dog"},{"id":"c","text":"pig"},{"id":"d","text":"fan"}],"answer":["d"]},{"ref":"q2","type":"slider","prompt":"How many letters are in the alphabet?","hint":"A to Z.","explanation":"There are 26 letters in the alphabet.","skill_tag":"alphabet.count","range":{"step":1,"min":0,"max":40,"unit":"letters"},"answer":{"value":26,"tolerance":0}},{"ref":"q3","type":"number","prompt":"How many sounds do you hear in the word dog? (d, o, g)","hint":"Say each sound slowly.","explanation":"d, o, g: three sounds.","skill_tag":"phonics.segmenting","answer":{"value":3,"tolerance":0}},{"ref":"q4","type":"multiple_choice","prompt":"Which word rhymes with cake?","hint":"Listen to the end of the word.","explanation":"Cake and bake both end in ''ake''.","skill_tag":"rhyme.match","options":[{"id":"a","text":"cat"},{"id":"b","text":"cup"},{"id":"c","text":"kite"},{"id":"d","text":"bake"}],"answer":["d"]},{"ref":"q5","type":"hotspot","prompt":"Tap the word that rhymes with cat.","hint":"Say ''cat'' and then say each name.","explanation":"Hat rhymes with cat.","skill_tag":"rhyme.match","scene":{"items":[{"id":"h1","emoji":"🎩","label":"hat","x":20,"y":40,"size":3},{"id":"h2","emoji":"🐶","label":"dog","x":50,"y":40,"size":3},{"id":"h3","emoji":"🚗","label":"car","x":80,"y":40,"size":3},{"id":"h4","emoji":"🌞","label":"sun","x":50,"y":80,"size":3}],"show_labels":false},"answer":["h1"]},{"ref":"q6","type":"multiple_choice","prompt":"Which word is spelled correctly?","hint":"It has a tricky ''ai''.","explanation":"The correct spelling is s-a-i-d.","skill_tag":"spelling.sight_words","options":[{"id":"a","text":"sayd"},{"id":"b","text":"sad-d"},{"id":"c","text":"sed"},{"id":"d","text":"said"}],"answer":["d"]},{"ref":"q7","type":"multiple_choice","prompt":"Which sentence is written correctly?","hint":"Look for a capital letter and a full stop.","explanation":"A sentence starts with a capital letter and ends with a full stop.","skill_tag":"sentences.punctuation","options":[{"id":"a","text":"the dog ran home"},{"id":"b","text":"the Dog ran Home."},{"id":"c","text":"The dog ran home"},{"id":"d","text":"The dog ran home."}],"answer":["d"]},{"ref":"q8","type":"fill_blank","prompt":"Fill in the gaps.","hint":"Think of the lesson.","explanation":"A sentence starts with a capital letter and ends with a full stop.","skill_tag":"sentences.punctuation","points":2,"text":"A sentence starts with a {b1} letter and ends with a {b2}.","blanks":[{"id":"b1","options":[{"id":"a","text":"wavy"},{"id":"b","text":"capital"},{"id":"c","text":"small"}]},{"id":"b2","options":[{"id":"a","text":"heart"},{"id":"b","text":"full stop"},{"id":"c","text":"star"}]}],"answer":{"b1":"b","b2":"b"}},{"ref":"q9","type":"order","prompt":"Drag the words into the right order to make a sentence.","hint":"Start with the word We.","explanation":"We play in the park. makes sense.","skill_tag":"sentences.order","points":2,"items":[{"id":"i2","text":"play"},{"id":"i4","text":"the"},{"id":"i3","text":"in"},{"id":"i5","text":"park."},{"id":"i1","text":"We"}],"answer":["i1","i2","i3","i4","i5"]},{"ref":"q10","type":"multi_select","prompt":"Which of these are naming words (nouns)? Pick all that apply.","hint":"A naming word names a thing.","explanation":"Frog and ball name things. Jump and run are actions.","skill_tag":"grammar.nouns","options":[{"id":"a","text":"ball"},{"id":"b","text":"run"},{"id":"c","text":"jump"},{"id":"d","text":"frog"}],"answer":["d","a"]},{"ref":"q11","type":"true_false","prompt":"Jump is an action word.","hint":"Can you do it with your body?","explanation":"Jump is something you do, so it is a verb.","skill_tag":"grammar.verbs","answer":[true]},{"ref":"q12","type":"match","prompt":"Match each word with the word that means the opposite.","hint":"Think of the very opposite.","explanation":"Hot and cold, day and night, open and shut are opposites.","skill_tag":"vocab.opposites","points":2,"left":[{"id":"l1","text":"hot"},{"id":"l2","text":"day"},{"id":"l3","text":"open"}],"right":[{"id":"r2","text":"night"},{"id":"r3","text":"shut"},{"id":"r1","text":"cold"}],"answer":{"l1":"r1","l2":"r2","l3":"r3"}},{"ref":"q13","type":"multiple_choice","prompt":"Sam has a blue hat. He puts it on his head. What does Sam put on his head?","hint":"Read the first sentence again.","explanation":"The text says Sam puts his blue hat on his head.","skill_tag":"reading.literal","options":[{"id":"a","text":"A red hat"},{"id":"b","text":"A shoe"},{"id":"c","text":"A cup"},{"id":"d","text":"A blue hat"}],"answer":["d"]},{"ref":"q14","type":"multiple_choice","prompt":"Ben puts on his coat and boots. Then he picks up his umbrella. What is the weather like?","hint":"Why would you take an umbrella?","explanation":"Coat, boots and an umbrella are clues that it is raining.","skill_tag":"reading.inference","options":[{"id":"a","text":"Snowy"},{"id":"b","text":"Hot"},{"id":"c","text":"Sunny"},{"id":"d","text":"Rainy"}],"answer":["d"]},{"ref":"q15","type":"multiple_choice","prompt":"Which sentence has a verb (action word)?","hint":"Find the word that tells what someone does.","explanation":"Runs is the action word in the first sentence.","skill_tag":"grammar.verbs","options":[{"id":"a","text":"The big red ball."},{"id":"b","text":"The girl runs home."},{"id":"c","text":"A happy little frog."}],"answer":["b"]}]}}')) INSERT OR IGNORE INTO lessons (id, slug, subject_id, title, summary, age_band, difficulty, estimated_minutes, unit, sort_order, status, current_version, content_json, source_json) SELECT 'd67551b1-d295-5041-a7c9-c75e91692133', json_extract(j,'$.lesson.slug'), json_extract(j,'$.lesson.subject'), json_extract(j,'$.lesson.title'), json_extract(j,'$.lesson.summary'), json_extract(j,'$.lesson.age_band'), json_extract(j,'$.lesson.difficulty'), json_extract(j,'$.lesson.estimated_minutes'), json_extract(j,'$.lesson.unit'), 3, 'published', 1, json_extract(j,'$.blocks'), j FROM src;
