WITH src(j) AS (VALUES ('{"schema_version":"1.0","lesson":{"slug":"diag-english-class-4","subject":"english","title":"English Check-In: Where Am I?","summary":"A friendly tour of word types, punctuation, tenses, prefixes and suffixes, synonyms and reading between the lines.","age_band":"9-10","difficulty":2,"estimated_minutes":60,"unit":"Week 1: Where am I?","learning_objectives":["Show what I know about nouns, verbs, adjectives and adverbs","Show what I know about punctuation and tenses","Show what I know about building words and reading clues"],"tags":["week-1","diagnostic"],"curriculum":{"course":"english-class-4","semester":1,"week":1}},"blocks":[{"type":"heading","text":"Welcome, Wordsmith!"},{"type":"text","markdown":"This is a **check-in**, not a test.\n\nGood writers are curious about words and not afraid to guess.\n\nShow us what you know and where you want to learn more."},{"type":"image","emoji":"✍️","alt":"Time to play with words!","caption":"Time to play with words!"},{"type":"heading","text":"Stop 1: The jobs words do"},{"type":"text","markdown":"Every word has a job. A **noun** names a person, place or thing. A **verb** is an action. An **adjective** describes a noun. An **adverb** tells us how, when or where something happens."},{"type":"explainer","title":"The jobs in a sentence","scenes":[{"caption":"The librarian smiled. Librarian is a noun.","items":[{"id":"a","emoji":"🧑‍🏫","x":30,"y":55,"size":3,"anim":"none","label":"noun"}]},{"caption":"Smiled is a verb. It is the action.","items":[{"id":"a","emoji":"🧑‍🏫","x":30,"y":55,"size":3,"anim":"none"},{"id":"b","emoji":"😊","x":70,"y":55,"size":3,"anim":"bounce","label":"verb"}]},{"caption":"Kind is an adjective. It describes the librarian.","items":[{"id":"a","emoji":"🧑‍🏫","x":30,"y":55,"size":3,"anim":"pulse","label":"kind"},{"id":"b","emoji":"😊","x":70,"y":55,"size":3,"anim":"none"}]},{"caption":"Warmly is an adverb. It tells us how she smiled.","items":[{"id":"a","emoji":"🧑‍🏫","x":30,"y":55,"size":3,"anim":"none"},{"id":"b","emoji":"😊","x":70,"y":55,"size":3,"anim":"pulse","label":"warmly"}]}]},{"type":"check","question":{"type":"multi_select","prompt":"Pick both verbs: The children laughed and played.","hint":"Which two words show actions?","options":[{"id":"a","text":"played"},{"id":"b","text":"children"},{"id":"c","text":"The"},{"id":"d","text":"laughed"}],"answer":["d","a"]}},{"type":"heading","text":"Stop 2: Punctuation"},{"type":"text","markdown":"**Capital letters** begin sentences and names. A **comma** separates the things in a list. **Speech marks** go round the exact words someone says. An **apostrophe** shows that letters are missing, or that something belongs to someone."},{"type":"explainer","title":"Capitals, commas and speech marks","scenes":[{"caption":"Ali said hello. Names start with a capital letter.","items":[{"id":"a","emoji":"🧒","x":50,"y":55,"size":3,"anim":"none","label":"Ali"}]},{"caption":"We pack a bag, a book and a bottle. Commas separate the list.","items":[{"id":"b1","emoji":"🎒","x":25,"y":55,"size":3,"anim":"none"},{"id":"b2","emoji":"📖","x":50,"y":55,"size":3,"anim":"none"},{"id":"b3","emoji":"🧴","x":75,"y":55,"size":3,"anim":"none"},{"id":"c","emoji":"🔹","x":37,"y":80,"size":1,"anim":"none","label":","}]},{"caption":"\"Hello,\" said Ali. Speech marks go round the spoken words.","items":[{"id":"a","emoji":"🧒","x":30,"y":55,"size":3,"anim":"none"},{"id":"s","emoji":"💬","x":70,"y":40,"size":3,"anim":"pulse","label":"\"Hello\""}]}]},{"type":"explainer","title":"What the apostrophe does","scenes":[{"caption":"Do not is the same as don''t.","items":[{"id":"a","emoji":"🅾️","x":30,"y":55,"size":3,"anim":"none","label":"do not"}]},{"caption":"The o is missing. An apostrophe takes its place.","items":[{"id":"a","emoji":"🅾️","x":30,"y":55,"size":3,"anim":"none","label":"do not"},{"id":"b","emoji":"⏬","x":55,"y":55,"size":2,"anim":"bounce"},{"id":"c","emoji":"✳️","x":80,"y":55,"size":3,"anim":"pulse","label":"don''t"}]},{"caption":"Ali''s bag means the bag belongs to Ali.","items":[{"id":"a","emoji":"🧒","x":30,"y":55,"size":3,"anim":"none","label":"Ali''s"},{"id":"b","emoji":"🎒","x":70,"y":55,"size":3,"anim":"bounce","label":"bag"}]}]},{"type":"check","question":{"type":"multiple_choice","prompt":"Which sentence uses an apostrophe correctly?","hint":"The book belongs to Fatima.","options":[{"id":"a","text":"Fatimas'' book is on the table."},{"id":"b","text":"Fatima''s book is on the table."},{"id":"c","text":"Fatima book''s is on the table."}],"answer":["b"]}},{"type":"check","question":{"type":"true_false","prompt":"A comma can be used to separate the things in a list.","hint":"Think of a shopping list.","answer":[true]}},{"type":"heading","text":"Stop 3: Tenses"},{"type":"text","markdown":"**Tense** tells us when something happens. Past: I walked. Present: I walk. Future: I will walk.\n\nSome verbs change in tricky ways, like go becomes went."},{"type":"explainer","title":"Past, present and future","scenes":[{"caption":"Yesterday, I walked.","items":[{"id":"a","emoji":"🚶","x":20,"y":55,"size":3,"anim":"none","label":"past: walked"},{"id":"b","emoji":"⬅️","x":20,"y":20,"size":2,"anim":"none"}]},{"caption":"Today, I walk.","items":[{"id":"a","emoji":"🚶","x":50,"y":55,"size":3,"anim":"bounce","label":"present: walk"}]},{"caption":"Tomorrow, I will walk.","items":[{"id":"a","emoji":"🚶","x":80,"y":55,"size":3,"anim":"none","label":"future: will walk"},{"id":"b","emoji":"➡️","x":80,"y":20,"size":2,"anim":"none"}]}]},{"type":"check","question":{"type":"match","prompt":"Match each verb to its past tense.","hint":"Some of them change a lot.","points":2,"left":[{"id":"l1","text":"go"},{"id":"l2","text":"eat"},{"id":"l3","text":"play"}],"right":[{"id":"r3","text":"played"},{"id":"r1","text":"went"},{"id":"r2","text":"ate"}],"answer":{"l1":"r1","l2":"r2","l3":"r3"}}},{"type":"heading","text":"Stop 4: Building words and meanings"},{"type":"text","markdown":"A **prefix** goes at the start of a word and changes its meaning, like un in unhappy. A **suffix** goes at the end, like ful in careful.\n\nClap the beats in a word. Un-hap-py has 3 beats, also called syllables."},{"type":"explainer","title":"Building new words","scenes":[{"caption":"Start with happy.","items":[{"id":"a","emoji":"😊","x":50,"y":55,"size":3,"anim":"none","label":"happy"}]},{"caption":"Add the prefix un. It means not.","items":[{"id":"a","emoji":"😊","x":65,"y":55,"size":3,"anim":"none","label":"happy"},{"id":"p","emoji":"🔹","x":30,"y":55,"size":3,"anim":"grow","label":"un"}]},{"caption":"Unhappy means not happy.","items":[{"id":"a","emoji":"😞","x":50,"y":55,"size":3,"anim":"none","label":"unhappy"}]}]},{"type":"check","question":{"type":"multiple_choice","prompt":"Which prefix makes happy mean not happy?","hint":"Think about unlock.","options":[{"id":"a","text":"ful"},{"id":"b","text":"un"},{"id":"c","text":"re"}],"answer":["b"]}},{"type":"text","markdown":"A **synonym** is a word with almost the same meaning. An **antonym** is a word with the opposite meaning."},{"type":"explainer","title":"Synonyms and antonyms","scenes":[{"caption":"Big and huge are synonyms. They mean almost the same.","items":[{"id":"a","emoji":"🐘","x":30,"y":55,"size":3,"anim":"none","label":"big"},{"id":"b","emoji":"🐋","x":70,"y":55,"size":3,"anim":"none","label":"huge"}]},{"caption":"Big and tiny are antonyms. They mean the opposite.","items":[{"id":"a","emoji":"🐘","x":30,"y":55,"size":3,"anim":"none","label":"big"},{"id":"b","emoji":"🐜","x":70,"y":55,"size":2,"anim":"none","label":"tiny"}]}]},{"type":"check","question":{"type":"multiple_choice","prompt":"Which word is a synonym of tiny?","hint":"It means almost the same.","options":[{"id":"a","text":"loud"},{"id":"b","text":"small"},{"id":"c","text":"huge"}],"answer":["b"]}},{"type":"heading","text":"Stop 5: Reading between the lines"},{"type":"text","markdown":"Good readers notice clues. Read this: Mia packed her bag the night before the trip. In the morning she woke early and ran to the window. Thick grey clouds covered the sky, but she grinned and pulled on her raincoat anyway. She could not wait to see the waterfall."},{"type":"image","emoji":"🌧️","alt":"Grey clouds over Mia''s trip.","caption":"Grey clouds over Mia''s trip."},{"type":"check","question":{"type":"multiple_choice","prompt":"How did Mia feel about the trip?","hint":"Look at what she did and what she said.","options":[{"id":"a","text":"Bored"},{"id":"b","text":"Excited"},{"id":"c","text":"Scared"}],"answer":["b"]}},{"type":"reveal","prompt":"Which clues in the story tell you how Mia felt?","answer_markdown":"She packed the night before, woke early, ran to the window, grinned and could not wait."},{"type":"activity","title":"Sentence builder","materials":["Paper and pencil"],"instructions":["Write a short sentence, like ''The dog barked.''","Make it better by adding an adjective and an adverb.","Read it aloud. Which words did you add?"]},{"type":"brain_game","game":"remember_order","title":"Writer''s memory","goal":"Watch the colours, then copy the order.","emojis":["🔴","🔵","🟡","🟢","🟣"]},{"type":"summary","points":["Words have jobs: nouns, verbs, adjectives and adverbs.","Punctuation helps the reader: capitals, commas, speech marks and apostrophes.","Tense tells us when something happens.","Prefixes and suffixes build new words.","Good readers notice clues."]},{"type":"callout","style":"tip","markdown":"When you are ready, start the quiz. It has 15 questions and takes about 15 minutes. Do your best!"},{"type":"glossary","terms":[{"term":"check-in","meaning":"A friendly game that shows us what you know. It is not a test."},{"term":"noun","meaning":"A word that names a person, place or thing."},{"term":"verb","meaning":"An action word."},{"term":"adjective","meaning":"A word that describes a noun."},{"term":"adverb","meaning":"A word that tells us how, when or where something happens."},{"term":"capital letters","meaning":"Big letters used at the start of sentences and names."},{"term":"comma","meaning":"A mark that separates things in a list."},{"term":"speech marks","meaning":"Marks that go round the exact words someone says."},{"term":"apostrophe","meaning":"A mark that shows missing letters or that something belongs to someone."},{"term":"tense","meaning":"Tells us when something happens: past, present or future."},{"term":"prefix","meaning":"Letters added to the start of a word to change its meaning."},{"term":"suffix","meaning":"Letters added to the end of a word."},{"term":"synonym","meaning":"A word with almost the same meaning as another word."},{"term":"antonym","meaning":"A word with the opposite meaning."}]}],"quiz":{"pass_percent":1,"shuffle_questions":false,"shuffle_options":true,"max_attempts":null,"questions":[{"ref":"q1","type":"multiple_choice","prompt":"Which word is a noun? A quiet librarian smiled.","hint":"It names a person.","explanation":"Librarian names a person, so it is a noun.","skill_tag":"grammar.nouns","options":[{"id":"a","text":"quiet"},{"id":"b","text":"smiled"},{"id":"c","text":"librarian"}],"answer":["c"]},{"ref":"q2","type":"multiple_choice","prompt":"Which word is the adverb? Birds sing sweetly.","hint":"It tells us how they sing.","explanation":"Sweetly tells us how the birds sing.","skill_tag":"grammar.adverbs","options":[{"id":"a","text":"Birds"},{"id":"b","text":"sweetly"},{"id":"c","text":"sing"}],"answer":["b"]},{"ref":"q3","type":"multi_select","prompt":"Pick the two verbs: We painted pictures and hung them up.","hint":"Find the action words.","explanation":"Painted and hung are actions.","skill_tag":"grammar.verbs","options":[{"id":"a","text":"hung"},{"id":"b","text":"pictures"},{"id":"c","text":"them"},{"id":"d","text":"painted"}],"answer":["d","a"]},{"ref":"q4","type":"multiple_choice","prompt":"Which sentence is correct?","hint":"One apostrophe for a missing letter, one for belonging.","explanation":"Can''t has a missing o and cat''s shows the toy belongs to the cat.","skill_tag":"punctuation.apostrophe","options":[{"id":"a","text":"I can''t find the cat toy''s."},{"id":"b","text":"I ca''nt find the cat''s toy."},{"id":"c","text":"I cant find the cats toy."},{"id":"d","text":"I can''t find the cat''s toy."}],"answer":["d"]},{"ref":"q5","type":"multiple_choice","prompt":"Which sentence uses speech marks correctly?","hint":"They go round the spoken words.","explanation":"Speech marks go round the exact words spoken.","skill_tag":"punctuation.speech_marks","options":[{"id":"a","text":"Come here, said \"Dad\"."},{"id":"b","text":"\"Come here said\" Dad."},{"id":"c","text":"\"Come here,\" said Dad."}],"answer":["c"]},{"ref":"q6","type":"match","prompt":"Link each verb to the way we say it in the past.","hint":"Some change a lot.","explanation":"Run becomes ran, swim becomes swam and walk becomes walked.","skill_tag":"grammar.tense","points":2,"left":[{"id":"l1","text":"run"},{"id":"l2","text":"swim"},{"id":"l3","text":"walk"}],"right":[{"id":"r2","text":"swam"},{"id":"r3","text":"walked"},{"id":"r1","text":"ran"}],"answer":{"l1":"r1","l2":"r2","l3":"r3"}},{"ref":"q7","type":"short_text","prompt":"Write the plural of child.","hint":"It is not childs.","explanation":"The plural of child is children.","skill_tag":"spelling.plurals","answer":{"accepted":["children"]}},{"ref":"q8","type":"multiple_choice","prompt":"The cake was gone from the plate. Tom''s sister had chocolate on her chin and a guilty smile. What can you tell?","hint":"Look at the clues about his sister.","explanation":"The chocolate and the guilty smile are clues.","skill_tag":"reading.inference","options":[{"id":"a","text":"Nobody made a cake"},{"id":"b","text":"The cake was never there"},{"id":"c","text":"Tom ate the cake"},{"id":"d","text":"Tom''s sister probably ate the cake"}],"answer":["d"]},{"ref":"q9","type":"multiple_choice","prompt":"Which word means to build again?","hint":"Re means again.","explanation":"The prefix re means again, so rebuild means build again.","skill_tag":"morphology.prefix","options":[{"id":"a","text":"unbuild"},{"id":"b","text":"prebuild"},{"id":"c","text":"buildful"},{"id":"d","text":"rebuild"}],"answer":["d"]},{"ref":"q10","type":"fill_blank","prompt":"Fill in the gaps.","hint":"One is at the start and one is at the end.","explanation":"Un is at the start, ful is at the end.","skill_tag":"morphology.affixes","points":2,"text":"The prefix in unkind is {b1}. The suffix in careful is {b2}.","blanks":[{"id":"b1","options":[{"id":"a","text":"ful"},{"id":"b","text":"un"},{"id":"c","text":"kind"}]},{"id":"b2","options":[{"id":"a","text":"un"},{"id":"b","text":"ful"},{"id":"c","text":"care"}]}],"answer":{"b1":"b","b2":"b"}},{"ref":"q11","type":"multiple_choice","prompt":"Which word is an antonym of ancient?","hint":"It means the opposite.","explanation":"Ancient means very old, so the opposite is modern.","skill_tag":"vocabulary.antonyms","options":[{"id":"a","text":"dusty"},{"id":"b","text":"huge"},{"id":"c","text":"old"},{"id":"d","text":"modern"}],"answer":["d"]},{"ref":"q12","type":"true_false","prompt":"A comma can separate the things in a list, like ''apples, pears and plums''.","hint":"Think of a shopping list.","explanation":"Commas separate things in a list.","skill_tag":"punctuation.comma","answer":[true]},{"ref":"q13","type":"order","prompt":"Put the words in order to make a sentence.","hint":"Start with The.","explanation":"The dog ran quickly. is correct.","skill_tag":"sentences.order","points":2,"items":[{"id":"i3","text":"ran"},{"id":"i4","text":"quickly."},{"id":"i2","text":"dog"},{"id":"i1","text":"The"}],"answer":["i1","i2","i3","i4"]},{"ref":"q14","type":"hotspot","prompt":"Tap the picture that shows a verb (an action).","hint":"A verb is something you do.","explanation":"Running is an action, so it is a verb.","skill_tag":"grammar.verbs","scene":{"items":[{"id":"h1","emoji":"🏃","label":"running","x":20,"y":40,"size":3},{"id":"h2","emoji":"🐶","label":"dog","x":50,"y":40,"size":3},{"id":"h3","emoji":"🍎","label":"apple","x":80,"y":40,"size":3},{"id":"h4","emoji":"🏠","label":"house","x":50,"y":80,"size":3}],"show_labels":false},"answer":["h1"]},{"ref":"q15","type":"slider","prompt":"How many beats (syllables) are in the word unhappy?","hint":"Clap: un-hap-py.","explanation":"Un-hap-py has 3 beats.","skill_tag":"morphology.syllables","range":{"step":1,"min":0,"max":6,"unit":"beats"},"answer":{"value":3,"tolerance":0}}]}}')) INSERT OR IGNORE INTO lessons (id, slug, subject_id, title, summary, age_band, difficulty, estimated_minutes, unit, sort_order, status, current_version, content_json, source_json) SELECT 'a31c10a8-4f02-5604-a44f-01fa167a9776', json_extract(j,'$.lesson.slug'), json_extract(j,'$.lesson.subject'), json_extract(j,'$.lesson.title'), json_extract(j,'$.lesson.summary'), json_extract(j,'$.lesson.age_band'), json_extract(j,'$.lesson.difficulty'), json_extract(j,'$.lesson.estimated_minutes'), json_extract(j,'$.lesson.unit'), 4, 'published', 1, json_extract(j,'$.blocks'), j FROM src;
INSERT OR IGNORE INTO course_lessons (course_id, lesson_id, position, semester, week) VALUES ('736a0b85-b107-5f53-ab88-cda06a05f74b', 'a31c10a8-4f02-5604-a44f-01fa167a9776', 101, 1, 1);
